import java.util.*;class Solution{public List<List<Integer>> getSkyline(int[][]b){List<int[]>e=new ArrayList<>();for(int[]x:b){e.add(new int[]{x[0],-x[2]});e.add(new int[]{x[1],x[2]});}e.sort((a,c)->a[0]!=c[0]?a[0]-c[0]:a[1]-c[1]);TreeMap<Integer,Integer>h=new TreeMap<>();h.put(0,1);List<List<Integer>>o=new ArrayList<>();int prev=0;for(int[]x:e){if(x[1]<0)h.merge(-x[1],1,Integer::sum);else{h.put(x[1],h.get(x[1])-1);if(h.get(x[1])==0)h.remove(x[1]);}int cur=h.lastKey();if(cur!=prev){o.add(Arrays.asList(x[0],cur));prev=cur;}}return o;}}
